  auto VERTEX_LATITUDE_DEG__ = VERTEX_LATITUDE_DEG ? _fbb.CreateVector<double>(*VERTEX_LATITUDE_DEG) : 0;
  auto VERTEX_ALTITUDE_M__ = VERTEX_ALTITUDE_M ? _fbb.CreateVector<double>(*VERTEX_ALTITUDE_M) : 0;
  auto RING_OFFSETS__ = RING_OFFSETS ? _fbb.CreateVector<uint32_t>(*RING_OFFSETS) : 0;
  auto RING_POLYGON_INDEXES__ = RING_POLYGON_INDEXES ? _fbb.CreateVector<uint32_t>(*RING_POLYGON_INDEXES) : 0;
  auto RING_ROLES__ = RING_ROLES ? _fbb.CreateVector<int8_t>(*RING_ROLES) : 0;
  auto POLYGON_LEVEL_VALUES__ = POLYGON_LEVEL_VALUES ? _fbb.CreateVector<double>(*POLYGON_LEVEL_VALUES) : 0;
  auto POLYGON_LEVEL_UNCERTAINTIES__ = POLYGON_LEVEL_UNCERTAINTIES ? _fbb.CreateVector<double>(*POLYGON_LEVEL_UNCERTAINTIES) : 0;
  auto POLYGON_AREA_KM2__ = POLYGON_AREA_KM2 ? _fbb.CreateVector<double>(*POLYGON_AREA_KM2) : 0;
