  auto CONTRIBUTING_EMITTERS__ = CONTRIBUTING_EMITTERS ? _fbb.CreateVector<::flatbuffers::Offset<CVPEmitterRef>>(*CONTRIBUTING_EMITTERS) : 0;
  auto RECEIVER_SET_ID__ = RECEIVER_SET_ID ? _fbb.CreateString(RECEIVER_SET_ID) : 0;
