  auto CONTRIBUTING_OBSTACLES__ = CONTRIBUTING_OBSTACLES ? _fbb.CreateVector<::flatbuffers::Offset<CVPObstacleRef>>(*CONTRIBUTING_OBSTACLES) : 0;
