inline const CVP *GetCVP(const void *buf) {
  return ::flatbuffers::GetRoot<CVP>(buf);
}

inline const CVP *GetSizePrefixedCVP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<CVP>(buf);
}

inline const char *CVPIdentifier() {
  return "$CVP";
}

inline bool CVPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CVPIdentifier());
}

inline bool SizePrefixedCVPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, CVPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyCVPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<CVP>(CVPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedCVPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<CVP>(CVPIdentifier());
}

inline void FinishCVPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CVP> root) {
  fbb.Finish(root, CVPIdentifier());
}

inline void FinishSizePrefixedCVPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<CVP> root) {
  fbb.FinishSizePrefixed(root, CVPIdentifier());
}

